//! ⚖️ Playbook-play app — binary command protocol surface (constitutional: protocol).
//!
//! `PlaybookOperation`'s `protocol::OpBinary` impl is generated by the `dsl::DslOps` derive on its
//! definition in the kernel crate `s/kernel/playbook/rs` — this crate only re-exposes the
//! encode/decode entry points under the app's own constitutional `protocol` slot.

use playbook_op::PlaybookOperation;
use protocol::OpBinary;

/// 📦 Encodes a `PlaybookOperation` to its binary command form.
pub fn encode_op(operation: &PlaybookOperation) -> Result<Vec<u8>, protocol::ProtocolError> {
    operation.encode_op()
}

/// 📖 Decodes a `PlaybookOperation` from its binary command form.
pub fn decode_op(bytes: &[u8]) -> Result<PlaybookOperation, protocol::ProtocolError> {
    PlaybookOperation::decode_op(bytes)
}

//#region 🧪Tests
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn op_binary_round_trips() {
        let operation = playbook_op::update_playbook_title_operation(Some("Recipe".into()));
        let bytes = encode_op(&operation).expect("encode");
        assert_eq!(decode_op(&bytes).expect("decode"), operation);
    }
}
//#endregion 🧪Tests
